)

type Agent struct {
	llm                llm.LLM
	memory             []memory.MemoryEntry
	tools              []tools.Tool
	maxIterations      int
	ModelName          string
	OnTextChunk        butler.OnTextChunkFunc
	OnTextComplete     butler.OnTextCompleteFunc
	OnThinkingChunk    butler.OnThinkingChunkFunc
	OnThinkingComplete butler.OnThinkingCompleteFunc
	OnToolCall         butler.OnToolCallFunc
	OnTurnComplete     butler.OnTurnCompleteFunc
}

func NewAgent(l llm.LLM) *Agent {
	return &Agent{
		llm:           l,
		memory:        []memory.MemoryEntry{},
		tools:         tools.StdToolset,
		maxIterations: 10, // Default max iterations as recommended by OpenRouter docs
		ModelName:     "unknown",
	}
}

// Mods
func (a *Agent) WithMemory(memory []memory.MemoryEntry) *Agent {
	a.memory = memory
	return a
}

func (a *Agent) WithModelName(modelName string) *Agent {
	a.ModelName = modelName
	return a
}

func (a *Agent) WitTools(tools []tools.Tool) *Agent {
	a.tools = tools
	return a
}

func (a *Agent) WithNoTools() *Agent {
	a.tools = []tools.Tool{}
	return a
}

func (a *Agent) WithMaxIterations(max int) *Agent {
	a.maxIterations = max
	return a
}

func (l *Agent) WithOnThinkingChunk(f butler.OnThinkingChunkFunc) *Agent {
	l.OnThinkingChunk = f
	return l
}

func (l *Agent) WithOnThinkingComplete(f butler.OnThinkingCompleteFunc) *Agent {
	l.OnThinkingComplete = f
	return l
}

func (l *Agent) WithOnTextChunk(f butler.OnTextChunkFunc) *Agent {
	l.OnTextChunk = f
	return l
}

func (l *Agent) WithOnTextComplete(f butler.OnTextCompleteFunc) *Agent {
	l.OnTextComplete = f
	return l
}

func (l *Agent) WithOnToolCall(f butler.OnToolCallFunc) *Agent {
	l.OnToolCall = f
	return l
}

func (l *Agent) WithOnTurnComplete(f butler.OnTurnCompleteFunc) *Agent {
	l.OnTurnComplete = f
	return l
}

// Mock for Memory stuff later this is where Agent will use it
func (a *Agent) AddMemoryEntry(entry memory.MemoryEntry) {
	a.memory = append(a.memory, entry)
}

// Memory stuff later
func (a *Agent) GetMemory() []memory.MemoryEntry {
	return a.memory
}

func (a *Agent) HandleToolCall(ctx context.Context, call tools.ToolCall) (string, error) {
	var tool tools.Tool
	for _, t := range a.tools {
		if t.Name == call.FunctionName {
			tool = t
			break
		}
	}

	argsPtr := reflect.New(tool.ArgType).Interface()

	// Convert the map[string]any into the concrete struct.
	// This works for ANY provider because we go through JSON bytes first.
	bytes, _ := json.Marshal(call.Arguments)
	if err := json.Unmarshal(bytes, argsPtr); err != nil {
		return "", fmt.Errorf("failed to unmarshal tool args: %w", err)
	}

	results := tool.Handler.Call([]reflect.Value{
		reflect.ValueOf(argsPtr).Elem(),
	})

	if len(results) > 1 && !results[1].IsNil() {
		return "", results[1].Interface().(error)
	}
	resultStr := results[0].String()

	if a.OnToolCall != nil {
		a.OnToolCall(tools.ToolCall{
			ID:           "toolID", // TODO: generate unique ID for tool call
			FunctionName: tool.Name,
			Arguments:    call.Arguments,
		})
	}
	// Maybe useful to debug later
	// if len(resultStr) > 100 {
	// 	color.Blue("Tool %s returned: %s", call.FunctionName, resultStr[:100])
	// } else {
	// 	color.Blue("Tool %s returned: %s", call.FunctionName, resultStr)
	// }

	return resultStr, nil
}

func (a *Agent) Run(ctx context.Context, prompt string) error {
	initMessage := memory.MemoryEntry{
		StepID:  a.nextStepID(),
		Source:  "user",
		Message: prompt,
	}
	a.AddMemoryEntry(initMessage)

	iterationCount := 0
	for iterationCount < a.maxIterations {
		iterationCount++

		var reasoning strings.Builder
		hooks := butler.EventHooks{
			OnTextChunk:    a.OnTextChunk,
			OnTextComplete: a.OnTextComplete,
			OnToolCall:     a.OnToolCall,
			OnTurnComplete: a.OnTurnComplete,
			OnThinkingChunk: func(chunk string) {
				reasoning.WriteString(chunk)
				if a.OnThinkingChunk != nil {
					a.OnThinkingChunk(chunk)
				}
			},
			OnThinkingComplete: func() {
				if a.OnThinkingComplete != nil {
					a.OnThinkingComplete()
				}
			},
		}

		result, err := a.llm.Stream(ctx, a.memory, a.tools, hooks)
		if err != nil {
			log.Fatal("Error calling LLM Stream: ", err)
			return err
		}

		entry := memory.MemoryEntry{
			StepID:  a.nextStepID(),
			Source:  "agent",
			Message: result.Text,
		}
		if reasoning.Len() > 0 {
			entry.ReasoningContent = reasoning.String()
		}
		if result.Metrics != nil {
			entry.Metrics = *result.Metrics
		}
		if len(result.ToolCalls) > 0 {
			entry.ToolCalls = mapToolCalls(result.ToolCalls)
		}

		if len(result.ToolCalls) > 0 {
			var results []memory.ObservationResult
			for _, call := range result.ToolCalls {
				// Ask user for confirmation before executing tool
				// var confirm bool
				// if err := huh.NewConfirm().
				// 	Title("Execute tool?").
				// 	Description(fmt.Sprintf("Do you want to execute %s?", call.FunctionName)).
				// 	Affirmative("Yes").
				// 	Negative("No").
				// 	Value(&confirm).
				// 	WithTheme(huh.ThemeCatppuccin()).
				// 	Run(); err != nil {
				// 	color.Red("Error getting confirmation: %v", err)
				// 	continue
				// }

				// if !confirm {
				// 	color.Red("Tool call %s was cancelled by the user.", call.FunctionName)
				// 	a.AddMemoryEntry(memory.MemoryEntry{
				// 		Role:       "tool",
				// 		Message:    "Tool call cancelled by user",
				// 		ToolName:   call.FunctionName,
				// 		ToolCallID: call.ID,
				// 	})
				// 	continue
				// }

				output, _ := a.HandleToolCall(ctx, call)
				results = append(results, memory.ObservationResult{
					SourceCallID: call.ID,
					Content:      output,
				})
			}
			entry.Observation = memory.Observation{Results: results}
		}

		a.AddMemoryEntry(entry)

		if len(result.ToolCalls) == 0 {
			break
		}
	}

	if iterationCount >= a.maxIterations {
		color.Yellow("\nWarning: Maximum iterations (%d) reached. The agent loop was terminated.\n", a.maxIterations)
	}

	return nil
}

func (a *Agent) nextStepID() int {
	return len(a.memory) + 1
}

func mapToolCalls(calls []tools.ToolCall) []memory.ToolCall {
	if len(calls) == 0 {
		return nil
	}
	toolCalls := make([]memory.ToolCall, 0, len(calls))
	for _, call := range calls {
		toolCalls = append(toolCalls, memory.ToolCall{
			ToolCallID:   call.ID,
			FunctionName: call.FunctionName,
			Arguments:    call.Arguments,
		})
	}
	return toolCalls
}

package bridge

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"sync/atomic"
	"time"

	"github.com/mightymoud/arlocode/internal/butler/agent"
	"github.com/mightymoud/arlocode/internal/butler/memory"
	"github.com/mightymoud/arlocode/internal/butler/tools"
)

type DirectBridge struct {
	agent      *agent.Agent
	events     chan AgentEvent
	cancelFn   context.CancelFunc
	responding atomic.Bool
}

func NewDirectBridge(a *agent.Agent) *DirectBridge {
	db := &DirectBridge{
		agent:  a,
		events: make(chan AgentEvent, 100),
	}
	db.agent.
		WithOnTextChunk(func(s string) {
			db.events <- TextChunkEvent{Text: s}
		}).
		WithOnTextComplete(func() {
			db.events <- TextCompleteEvent{}
		}).
		WithOnThinkingChunk(func(s string) {
			db.events <- ThinkingChunkEvent{Text: s}
		}).
		WithOnThinkingComplete(func() {
			db.events <- ThinkingCompleteEvent{}
		}).
		WithOnToolCall(func(tc tools.ToolCall) {
			db.events <- ToolCallEvent{ToolCall: tc}
		}).
		WithOnTurnComplete(func() {
			db.events <- TurnCompleteEvent{}
		})

	return db
}

func (db *DirectBridge) Run(ctx context.Context, prompt string) error {
	ctx, db.cancelFn = context.WithCancel(ctx)
	db.responding.Store(true)

	go func() {
		err := db.agent.Run(ctx, prompt)
		db.responding.Store(false)
		if err != nil {
			db.events <- ErrorEvent{Err: err}
		}
		db.events <- TurnCompleteEvent{}
	}()

	return nil
}

func (db *DirectBridge) IsResponding() bool {
	return db.responding.Load()
}

func (db *DirectBridge) Events() <-chan AgentEvent {
	return db.events
}

func (db *DirectBridge) Cancel() error {
	if db.cancelFn != nil {
		db.cancelFn()
	}
	return nil
}
func (db *DirectBridge) Close() error {
	close(db.events)
	return nil
}

type atifAgent struct {
	Name       string  `json:"name"`
	Version    string  `json:"version"`
	ModelName  string  `json:"model_name,omitempty"`
}

type atifTrajectory struct {
	SchemaVersion string           `json:"schema_version"`
	SessionID     string           `json:"session_id"`
	Agent         atifAgent        `json:"agent"`
	Steps         []atifStep       `json:"steps"`
	FinalMetrics  atifFinalMetrics `json:"final_metrics"`
}

type atifFinalMetrics struct {
	TotalPromptTokens     int                    `json:"total_prompt_tokens,omitempty"`
	TotalCompletionTokens int                    `json:"total_completion_tokens,omitempty"`
	TotalCachedTokens     int                    `json:"total_cached_tokens,omitempty"`
	TotalCostUSD          float64                `json:"total_cost_usd,omitempty"`
	TotalSteps            int                    `json:"total_steps"`
	Extra                 map[string]interface{} `json:"extra,omitempty"`
}

type atifStep struct {
	StepID           int                    `json:"step_id"`
	Timestamp        string                 `json:"timestamp,omitempty"`
	Source           string                 `json:"source"`
	ModelName        string                 `json:"model_name,omitempty"`
	ReasoningEffort  interface{}            `json:"reasoning_effort,omitempty"`
	Message          string                 `json:"message"`
	ReasoningContent string                 `json:"reasoning_content,omitempty"`
	ToolCalls        []memory.ToolCall      `json:"tool_calls,omitempty"`
	Observation      *memory.Observation    `json:"observation,omitempty"`
	Metrics          *memory.Metrics        `json:"metrics,omitempty"`
	Extra            map[string]interface{} `json:"extra,omitempty"`
}

func (db *DirectBridge) ExportATIF(path string) (string, error) {
	steps := db.agent.GetMemory()
	exportSteps := make([]atifStep, 0, len(steps))

	sessionID := fmt.Sprintf("session-%d", time.Now().UnixNano())
	final := atifFinalMetrics{
		TotalSteps: len(steps),
	}

	for _, step := range steps {
		exportStep := atifStep{
			StepID:           step.StepID,
			Timestamp:        step.Timestamp,
			Source:           step.Source,
			ModelName:        step.ModelName,
			ReasoningEffort:  step.ReasoningEffort,
			Message:          step.Message,
			ReasoningContent: step.ReasoningContent,
			ToolCalls:        step.ToolCalls,
			Extra:            step.Extra,
		}

		if hasObservation(step.Observation) {
			obs := step.Observation
			exportStep.Observation = &obs
		}
		if hasMetrics(step.Metrics) {
			m := step.Metrics
			exportStep.Metrics = &m

			final.TotalPromptTokens += m.PromptTokens
			final.TotalCompletionTokens += m.CompletionTokens
			final.TotalCachedTokens += m.CachedTokens
			final.TotalCostUSD += m.CostUSD
		}

		exportSteps = append(exportSteps, exportStep)
	}

	traj := atifTrajectory{
		SchemaVersion: "ATIF-v1.5",
		SessionID:     sessionID,
		Agent: atifAgent{
			Name:      "arlocode",
			Version:   "unknown",
			ModelName: db.agent.ModelName,
		},
		Steps:        exportSteps,
		FinalMetrics: final,
	}

	if path == "" || path == "." {
		path = fmt.Sprintf("atif_trajectory_%s.json", sessionID)
	}

	bytes, err := json.MarshalIndent(traj, "", "  ")
	if err != nil {
		return "", err
	}
	if err := os.WriteFile(path, bytes, 0644); err != nil {
		return "", err
	}
	return path, nil
}

func hasObservation(obs memory.Observation) bool {
	return len(obs.Results) > 0
}

func hasMetrics(m memory.Metrics) bool {
	return m.PromptTokens != 0 ||
		m.CompletionTokens != 0 ||
		m.CachedTokens != 0 ||
		m.CostUSD != 0 ||
		len(m.PromptTokenIDs) > 0 ||
		len(m.CompletionTokenIDs) > 0 ||
		len(m.Logprobs) > 0 ||
		(len(m.Extra) > 0)
}

